How do I implement a simple stack in C?

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t size, cap;
} Stack;

static int push(Stack *s, int v) {
    if (s->size == s->cap) {
        size_t ncap = s->cap ? s->cap * 2 : 2;
        int *nd = realloc(s->data, ncap * sizeof *nd);
        if (!nd) return 0;
        s->data = nd; s->cap = ncap;
    }
    s->data[s->size++] = v;
    return 1;
}

int main(void) {
    Stack s = {0};
    for (int i = 1; i <= 5; i++) push(&s, i * 10);
    while (s.size) printf("%d ", s.data[--s.size]);
    printf("\n");
    free(s.data);
    return 0;
}
```

