Convert this Python to TypeScript:

```python
def bubble_sort(arr):
    arr = list(arr)
    for end in range(len(arr) - 1, 0, -1):
        swapped = False
        for i in range(end):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True
        if not swapped:
            break
    return arr
```

Here's the TypeScript equivalent:

```typescript
function bubbleSort(input: number[]): number[] {
  const arr = [...input];
  for (let end = arr.length - 1; end > 0; end--) {
    let swapped = false;
    for (let i = 0; i < end; i++) {
      if (arr[i] > arr[i + 1]) {
        [arr[i], arr[i + 1]] = [arr[i + 1], arr[i]];
        swapped = true;
      }
    }
    if (!swapped) break;
  }
  return arr;
}
```

The logic is the same as the Python version. The type annotations are erased at runtime; they just let the compiler catch mistakes like passing a string where a number is expected. For example, `bubble_sort([5, 2, 9, 1, 7])` gives `1 2 5 7 9` in both versions.

