When is a Bloom filter better than a set?

```python
import hashlib

class Bloom:
    def __init__(self, bits=256, hashes=3):
        self.bits, self.k, self.v = bits, hashes, 0
    def _idx(self, item):
        for i in range(self.k):
            h = hashlib.sha256(f"{i}:{item}".encode()).digest()
            yield int.from_bytes(h[:4], "big") % self.bits
    def add(self, item):
        for i in self._idx(item):
            self.v |= 1 << i
    def might_contain(self, item):
        return all(self.v >> i & 1 for i in self._idx(item))

b = Bloom()
for w in ["alice", "bob", "carol"]:
    b.add(w)
print(all(b.might_contain(w) for w in ["alice", "bob", "carol"]), b.might_contain("zed"))
```

