    cells[(floor(x / R), floor(y / R))].append(i)

pairs = set()
for (cx, cy), ids in cells.items():
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            for j in cells.get((cx + dx, cy + dy), []):
                for i in ids:
                    if i < j and hypot(pts[i][0] - pts[j][0], pts[i][1] - pts[j][1]) <= R:
                        pairs.add((i, j))
