class TtlCache {
  constructor(ttlMs, now = () => Date.now()) {
    this.ttl = ttlMs;
    this.now = now;          // injectable clock, so expiry can be tested without waiting
    this.map = new Map();
  }
  set(k, v) { this.map.set(k, { v, exp: this.now() + this.ttl }); }
  get(k) {
