class Ring:
    def __init__(self, n):
        self.buf, self.n, self.start, self.size = [None] * n, n, 0, 0
    def push(self, x):
        end = (self.start + self.size) % self.n
        self.buf[end] = x
        if self.size < self.n:
            self.size += 1
        else:
            self.start = (self.start + 1) % self.n
    def items(self):
        return [self.buf[(self.start + i) % self.n] for i in range(self.size)]

